import math

def wsd_factor(step, warmup=100, stable=700, decay=200,
               decay_type="1-sqrt", min_lr_ratio=0.0):
    if step < warmup:
        f = step / warmup
        return f * (1 - min_lr_ratio) + min_lr_ratio
    if step < warmup + stable:
        return 1.0
    if step < warmup + stable + decay:
        p = (step - warmup - stable) / decay
        if decay_type == "linear":
            f = 1 - p
        elif decay_type == "cosine":
            f = 0.5 * (1 + math.cos(math.pi * p))
        else:  # "1-sqrt"
            f = 1 - math.sqrt(p)
        return f * (1 - min_lr_ratio) + min_lr_ratio
    return min_lr_ratio

WARMUP = 100

def wsd(step, decay_start, decay_len, shape="1-sqrt"):
    if step < WARMUP: return (step + 1) / WARMUP
    if step < decay_start: return 1.0
    p = min((step - decay_start) / decay_len, 1.0)
    return 1 - math.sqrt(p) if shape == "1-sqrt" else 1 - p

def cosine(step, total, floor=0.1):
    if step < WARMUP: return (step + 1) / WARMUP
    p = (step - WARMUP) / (total - WARMUP)
    return floor + (1 - floor) * 0.5 * (1 + math.cos(math.pi * p))

